changeSet.sql:
DELETE sup
FROM system_user_permissions sup
JOIN system_permissions sp ON sp.id = sup.system_permission_id
WHERE LOWER(TRIM(sp.code)) = 'admin.all';

DELETE FROM system_permissions
WHERE LOWER(TRIM(code)) = 'admin.all';

DELETE rp
FROM role_permissions rp
JOIN permissions p ON p.id = rp.permission_id
WHERE LOWER(TRIM(p.code)) = 'admin.all';

DELETE FROM permissions
WHERE LOWER(TRIM(code)) = 'admin.all';

DELETE brp
FROM base_role_permissions brp
JOIN base_permissions bp ON bp.id = brp.base_permission_id
WHERE LOWER(TRIM(bp.code)) = 'admin.all';

DELETE FROM base_permissions
WHERE LOWER(TRIM(code)) = 'admin.all';
